        XCTAssertEqual(difference.reference?.sourceValue,.integer(14))
        XCTAssertEqual(difference.candidate?.sourceValue,.integer(10))
        XCTAssertNil(result.observations[2].admittedProtocolPricesRub.median)
        // Even re-sealing a modified price or invented contract cannot satisfy the archive pin.
        var catalogFields=try XCTUnwrap(catalogRaw.fields)
        var records=try XCTUnwrap(catalogFields["records"]?.elements)
        var record=try XCTUnwrap(records[0].fields)
        record["signed_contract_price_rub"] = .text("28400")
        records[0] = .object(record);catalogFields["records"] = .array(records)
        catalogFields.removeValue(forKey:"catalog_sha256")
        catalogFields["catalog_sha256"] = .text(try CompanyHistoricalJSON.object(catalogFields).digest())
        XCTAssertThrowsError(try CompanyHistoricalCatalog.verified(.object(catalogFields),identity:identity,item:item))
        var previewFields=try XCTUnwrap(previewRaw.fields)
        previewFields["cross_procurement_price_rub"] = .text("74000")
        previewFields.removeValue(forKey:"preview_sha256")
        previewFields["preview_sha256"] = .text(try CompanyHistoricalJSON.object(previewFields).digest())
        XCTAssertThrowsError(try CompanyHistoricalPreview.verified(.object(previewFields),identity:identity,item:item,catalog:catalog,selection:selected))
        let wrongOrder=CompanyHistoricalSelection(referenceRegistryNumber:selected.referenceRegistryNumber,selectedRegistryNumbers:Array(selected.selectedRegistryNumbers.reversed()),confirmReviewSourceScope:true)
        XCTAssertThrowsError(try CompanyHistoricalPreview.verified(previewRaw,identity:identity,item:item,catalog:catalog,selection:wrongOrder))
    }

